using BaseLib.Patches.Content;
using MegaCrit.Sts2.Core.Entities.Cards;

namespace Believer.BelieverCode.Keywords;

/// <summary>
/// Stable custom card-keyword markers. These are generated by BaseLib at ModelDb initialization;
/// the localization keys are BELIEVER-MIRACLE.* and BELIEVER-ENHANCED_MIRACLE.*.
/// </summary>
public static class BelieverKeywords
{
    /// <summary>Marks a normal, collectible 神迹 / Miracle rare card.</summary>
    [CustomEnum("MIRACLE")]
    [KeywordProperties(AutoKeywordPosition.After)]
    public static CardKeyword Miracle;

    /// <summary>Marks a temporary enhanced Miracle generated only by Omniscience.</summary>
    [CustomEnum("ENHANCED_MIRACLE")]
    [KeywordProperties(AutoKeywordPosition.After)]
    public static CardKeyword EnhancedMiracle;
}
